package com.bank.djoin.model;

// Statistics for one side of a join: estimated vs actual size.
public class SideStats {
    private final String name;
    private final long estimatedBytes;
    private final long actualBytes;  // known only after an earlier stage runs

    public SideStats(String name, long estimatedBytes, long actualBytes) {
        this.name = name;
        this.estimatedBytes = estimatedBytes;
        this.actualBytes = actualBytes;
    }
    public String getName() { return name; }
    public long getEstimatedBytes() { return estimatedBytes; }
    public long getActualBytes() { return actualBytes; }
}
