package com.bank.djoin.join;

import com.bank.djoin.model.SideStats;
import java.util.logging.Logger;

// Catalyst-style initial planner: uses ESTIMATES to pick a strategy.
public class JoinPlanner {
    private static final Logger log = Logger.getLogger(JoinPlanner.class.getName());
    private final long broadcastThreshold;

    public JoinPlanner(long broadcastThreshold) {
        this.broadcastThreshold = broadcastThreshold;
    }

    public JoinPlan planInitial(SideStats small) {
        if (small.getEstimatedBytes() <= broadcastThreshold) {
            log.info("initial plan: BROADCAST (estimate already small)");
            return new JoinPlan("BROADCAST");
        }
        log.info(() -> "initial plan: SORT_MERGE (estimate " + small.getEstimatedBytes()
                + "B exceeds threshold)");
        return new JoinPlan("SORT_MERGE");
    }
}
