package com.bank.djoin.join;

import com.bank.djoin.model.SideStats;
import java.util.logging.Logger;

// Runtime optimizer: switch SORT_MERGE -> BROADCAST using ACTUAL size,
// and enable the local shuffle reader for the large side.
public class AqeJoinOptimizer {
    private static final Logger log = Logger.getLogger(AqeJoinOptimizer.class.getName());
    private final long broadcastThreshold;

    public AqeJoinOptimizer(long broadcastThreshold) {
        this.broadcastThreshold = broadcastThreshold;
    }

    public JoinPlan reoptimize(JoinPlan plan, SideStats small, SideStats large) {
        if ("SORT_MERGE".equals(plan.strategy)
                && small.getActualBytes() <= broadcastThreshold) {
            log.info(() -> "AQE: actual " + small.getName() + " size "
                    + small.getActualBytes() + "B <= threshold → switch to BROADCAST");
            plan.strategy = "BROADCAST";

            // The large side was already shuffled; a broadcast join doesn't need the
            // repartition, so read that shuffle output LOCALLY (no network fetch).
            plan.localShuffleReader = true;
            log.info(() -> "AQE: enable local shuffle reader for '" + large.getName()
                    + "' — read already-written shuffle on each executor, no network");
        } else {
            log.info("AQE: keep SORT_MERGE (actual small side still too large to broadcast)");
        }
        return plan;
    }
}
