package com.bank.djoin;

import com.bank.djoin.join.*;
import com.bank.djoin.model.SideStats;
import java.util.logging.*;

public class DynamicJoinDemo {
    private static final Logger log = Logger.getLogger(DynamicJoinDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new DJoinLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        long threshold = 10_485_760; // 10 MB

        // Dimension (branch) looked big statically, but is tiny after a filter.
        SideStats branchDim = new SideStats("branch_dim", 500_000_000L, 8_000_000L);
        // Fact (transactions) is large on both estimate and actual.
        SideStats txnFact = new SideStats("txn_fact", 20_000_000_000L, 20_000_000_000L);

        // Catalyst initial plan from estimate → SORT_MERGE.
        JoinPlan plan = new JoinPlanner(threshold).planInitial(branchDim);
        log.info(() -> "after initial plan: strategy=" + plan.strategy);

        // AQE runtime: switch to broadcast + local shuffle reader.
        plan = new AqeJoinOptimizer(threshold).reoptimize(plan, branchDim, txnFact);
        final JoinPlan fp = plan;
        log.info(() -> "final: strategy=" + fp.strategy
                + ", localShuffleReader=" + fp.localShuffleReader);
    }
}

